-- Additive only: existing contacts, interactions and opportunities are preserved.
ALTER TABLE customers ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE, ADD INDEX idx_customer_assignment_status (assigned_employee_id,archived,id);
ALTER TABLE customer_interactions ADD COLUMN employee_visible BOOLEAN NOT NULL DEFAULT FALSE, ADD INDEX idx_employee_contact_history(customer_id,employee_id,employee_visible,id);
CREATE TABLE client_cases (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT NOT NULL,request_id VARCHAR(36) NOT NULL UNIQUE,subject VARCHAR(200) NOT NULL,description VARCHAR(4000) NOT NULL,status VARCHAR(20) NOT NULL,created_at DATETIME(6) NOT NULL,CONSTRAINT fk_client_case_customer FOREIGN KEY(customer_id) REFERENCES customers(id),INDEX idx_client_case_owner(customer_id,id),INDEX idx_client_case_status(status,id));
CREATE TABLE client_case_messages (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,case_id BIGINT NOT NULL,request_id VARCHAR(36) NOT NULL UNIQUE,body VARCHAR(4000) NOT NULL,sender_kind VARCHAR(10) NOT NULL,author_id BIGINT NOT NULL,created_at DATETIME(6) NOT NULL,CONSTRAINT fk_client_message_case FOREIGN KEY(case_id) REFERENCES client_cases(id),INDEX idx_client_message_page(case_id,id));
CREATE TABLE client_case_events (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,case_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,author_id BIGINT NOT NULL,created_at DATETIME(6) NOT NULL,CONSTRAINT fk_client_event_case FOREIGN KEY(case_id) REFERENCES client_cases(id),INDEX idx_client_event_page(case_id,id));
-- No FK is added to historical commercial tables here: any preexisting orphan must first be reconciled without deleting data.
